import json,re
d=json.load(open('mat.json'))
out=[]
def walk(n):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif t=='heading': out.append('\n\n## '+n.get('text','')+'\n')
        elif t=='paragraph':
            out.append('\n')
            for c in n.get('inlineContent',[]): walk(c)
            out.append('\n')
        else:
            for k,v in n.items(): walk(v)
    elif isinstance(n,list):
        for i in n: walk(i)
walk(d.get('primaryContentSections',[]))
walk(d.get('sections',[]))
txt=''.join(out)
txt=re.sub(r'\n{3,}','\n\n',txt)
open('mat.txt','w').write(txt)
print(txt[:8000])
